INSERT INTO `projects` (`project_id`, `project_manager_id`, `name`, `description`, `status`, `priority`, `start_date`, `deadline`, `progress`, `deleted_at`, `created_at`, `updated_at`) VALUES
(1, 1, 'Smart Project Task Management & Resource Scheduling System', 'Freethink flagship system featuring CPM-based automated resource scheduling, DHTMLX Gantt timeline visualization, dynamic holiday and leave capacity constraints, and real-time task progress tracking.', 'IN_PROGRESS', 'CRITICAL', '2026-08-23', '2026-10-07', '68.00', NULL, '2026-09-17 12:05:32', '2026-09-17 12:05:32'),
(2, 1, 'Simple Login System', 'A Vue-based login and authentication learning project using Pinia for state management and Quasar for modern UI components.', 'COMPLETED', 'HIGH', '2026-07-29', '2026-08-22', '100.00', NULL, '2026-09-17 12:05:32', '2026-09-17 12:05:32'),
(3, 1, 'Enterprise Booking & Reservation Engine', 'A comprehensive booking and reservation management system featuring schedule coordination, customer booking workflows, and real-time availability management.', 'IN_PROGRESS', 'HIGH', '2026-09-02', '2026-10-17', '42.00', NULL, '2026-09-17 12:05:32', '2026-09-17 12:05:32'),
(4, 1, 'Cloud Infrastructure & Microservices Migration', 'Enterprise containerization, Kubernetes cluster orchestration, Kafka event streaming pipelines, and distributed tracing setup.', 'IN_PROGRESS', 'CRITICAL', '2026-08-28', '2026-10-12', '54.00', NULL, '2026-09-17 12:05:32', '2026-09-17 12:05:32'),
(5, 1, 'Real-Time Telemetry & AI Analytics Platform', 'Time-series telemetry ingestion, automated anomaly detection, executive dashboard KPIs, and capacity forecasting ML models.', 'IN_PROGRESS', 'HIGH', '2026-09-07', '2026-10-22', '35.00', NULL, '2026-09-17 12:05:32', '2026-09-17 12:05:32');
