(1, 1, 1, NULL, NULL, 'STANDARD', 'Critical Path Scheduling Engine & Urgency Scoring', 'Implement CPM topological sort, cycle detection, urgency score sorting, and hourly precision allocation.', 'CRITICAL', 'COMPLETED', '2026-09-07', NULL, NULL, '2026-08-24 09:00:00', '2026-09-07 17:00:00', '32.00', '32.00', '100.00', 0, 0, NULL, '2026-09-17 12:05:32', '2026-09-17 12:05:32'),
(2, 1, 1, NULL, NULL, 'STANDARD', 'Task Sessions & Live Tracking Engine', 'Schema and backend service for live start/stop task tracking sessions, active session sync, and elapsed time calculation.', 'HIGH', 'IN_PROGRESS', '2026-09-25', '2026-09-17 10:00:00', '2026-09-17 16:00:00', '2026-09-12 09:30:00', NULL, '24.00', '18.00', '75.00', 0, 0, NULL, '2026-09-17 12:05:32', '2026-09-17 12:05:34'),
(3, 1, 1, NULL, NULL, 'STANDARD', 'Bottleneck Task Detection & Impact Analysis', 'Service to calculate task slack time and alert on bottleneck tasks delaying downstream milestones.', 'HIGH', 'SCHEDULED', '2026-10-05', '2026-09-17 16:00:00', '2026-09-21 16:00:00', NULL, NULL, '16.00', '0.00', '0.00', 0, 0, NULL, '2026-09-17 12:05:32', '2026-09-17 12:05:34'),
